"<!doctype html>
<html lang=\"sr\">
<head>
<meta charset=\"utf-8\">
<meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">
<title>VICE GRID '98 — Deluxe Edition</title>
<style>
@page {
    size: A4 landscape;
    margin: 10mm;
    background-color: #080b0e;
}
* { box-sizing: border-box; }
body {
    margin: 0;
    padding: 0;
    background: #080b0e;
    color: #e9e7dc;
    font-family: ui-monospace, Consolas, monospace;
    display: flex;
    justify-content: center;
    align-items: center;
    height: 100vh;
}
#app {
    width: 100%;
    max-width: 1240px;
    padding: 10px;
}
header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 8px;
    border-bottom: 2px solid #2d3b42;
    padding-bottom: 6px;
}
h1 {
    font-size: 19px;
    letter-spacing: 2px;
    color: #d8d994;
    margin: 0;
    text-shadow: 0 2px 4px rgba(0,0,0,0.8);
}
.hud {
    display: flex;
    gap: 8px;
}
.chip {
    background: #151e24;
    border: 1px solid #3c4e56;
    padding: 6px 12px;
    font-size: 13px;
    color: #c5d0d3;
    border-radius: 3px;
    box-shadow: inset 0 1px 3px rgba(0,0,0,0.5);
}
canvas {
    width: 100%;
    height: auto;
    display: block;
    border: 4px solid #3c4642;
    background: #1b2628;
    image-rendering: pixelated;
    box-shadow: 0 16px 50px #000, inset 0 0 80px rgba(0,0,0,0.6);
    border-radius: 4px;
}
#bottom {
    display: grid;
    grid-template-columns: 1fr auto;
    gap: 12px;
    margin-top: 8px;
}
#mission {
    background: #151e24;
    border-left: 4px solid #d8d994;
    padding: 8px 12px;
    font-size: 13px;
    color: #cfd8d6;
}
#help {
    text-align: right;
    color: #899895;
    font-size: 11px;
    line-height: 1.5;
}
#touch { display:none; position:fixed; inset:auto 12px 14px; z-index:20; justify-content:space-between; align-items:end; pointer-events:none; }
.pad { display:grid; grid-template-columns:repeat(3,48px); grid-template-rows:repeat(2,44px); gap:4px; pointer-events:auto; }
.pad button,.action button { background:#172329dd; color:#f1df84; border:1px solid #8c9a8b; border-radius:6px; padding:0; font-size:17px; touch-action:none; }
.pad button:active,.action button:active { background:#b78c36; color:#101619; }
.pad .empty { visibility:hidden; }
.action { display:flex; gap:7px; pointer-events:auto; }
.action button { width:58px; height:48px; font-size:12px; }
#pause { display:none; position:fixed; inset:0; z-index:30; background:#080b0edb; place-items:center; text-align:center; }
#pause .box { background:#151e24; border:2px solid #d8d994; padding:25px 35px; box-shadow:0 12px 40px #000; }
@media (max-width:760px) { body {height:auto; min-height:100dvh; align-items:flex-start;} #app {padding:7px;} header {flex-wrap:wrap; gap:6px;} h1 {font-size:14px;} .chip {font-size:10px; padding:4px 6px;} #bottom {grid-template-columns:1fr;} #help {text-align:left;} #touch {display:flex;} canvas {max-height:68vh; object-fit:contain;} }
#toast {
    position: fixed;
    top: 24px;
    left: 50%;
    transform: translateX(-50%);
    background: #0d1419;
    border: 2px solid #d8d994;
    color: #fff;
    padding: 10px 20px;
    font-size: 14px;
    display: none;
    z-index: 10;
    box-shadow: 0 8px 24px rgba(0,0,0,0.8);
    border-radius: 4px;
}
</style>
</head>
<body>
<div id=\"app\">
<header>
    <h1>VICE GRID ’98 <span style=\"color:#7f9094; font-size:14px;\">// 2x SCALE GTA 2 EDITION</span></h1>
    <div class=\"hud\">
        <span class=\"chip\" id=\"cash\">$ 250</span>
        <span class=\"chip\" id=\"time\">08:00</span>
        <span class=\"chip\" id=\"weather\">☀️ SUNNY</span>
        <span class=\"chip\" id=\"wanted\">POLICE ☆☆☆☆☆</span>
    </div>
</header>
<canvas id=\"game\" width=\"1024\" height=\"600\"></canvas>
<div id=\"bottom\">
    <div id=\"mission\"><b style=\"color:#d8d994\">GRADSKI POSAO</b><div id=\"task\">Istražuj grad. Ulice i zgrade su 2x veće!</div></div>
    <div id=\"help\">WASD / strelice — kretanje, vožnja i PLIVANJE · SPACE — ručna / drift<br>E / ENTER — uđi/izađi iz auta · Zgrade i ulice udvostručene u veličini!</div>
</div>
</div>
<div id=\"toast\"></div>
<div id=\"touch\">
  <div class=\"pad\"><button class=\"empty\"></button><button data-key=\"w\">▲</button><button class=\"empty\"></button><button data-key=\"a\">◀</button><button data-key=\"s\">▼</button><button data-key=\"d\">▶</button></div>
  <div class=\"action\"><button data-key=\"e\">ULAZ / MISIJA</button><button data-key=\" \">DRIFT</button></div>
</div>
<div id=\"pause\"><div class=\"box\"><h1>PAUZA</h1><p>Igra je zaustavljena.</p><p>WASD / strelice — kretanje · E — interakcija · SPACE — drift</p><button id=\"resume\">NASTAVI</button></div></div>

<script>
(()=>{
const c=document.querySelector('#game'), g=c.getContext('2d'), W=c.width, H=c.height, T=224, NX=18, NY=14, WW=NX*T, WH=NY*T;
const R=(a,b)=>a+Math.random()*(b-a), P=a=>a[Math.floor(Math.random()*a.length)], C=(v,a,b)=>Math.max(a,Math.min(b,v));
const keys={}, cam={x:0,y:0};
let cash=250, minutes=8*60, heat=0, job=0, toast=0, last=performance.now();
let weatherState = 'SUNNY', weatherTimer = 60, paused = false, completedJobs = 0;
const player={x:3*T+112, y:3*T+112, angle:0, walk:0, car:null, isSwimming:false, swimAnim:0};
const roadsX=[], roadsY=[], buildings=[], parks=[], water=[], bridges=[], cars=[], peds=[], skidMarks=[], particles=[];

for(let x=0;x<NX;x++) if(x%3===0) roadsX.push(x);
for(let y=0;y<NY;y++) if(y%3===0) roadsY.push(y);

const riverStart=6*T, riverEnd=8*T, bridgeXs=[6, 12];

function isWater(x,y){
    if(y < riverStart || y >= riverEnd) return false;
    for(let bx of bridgeXs){
        let bxPx = bx * T;
        if(x >= bxPx - 12 @COMMENT_BODY@@COMMENT_BODY@ x < bxPx + T * 2 + 12) return false;
    }
    return true;
}

function roadAt(x,y){
    let tx=Math.floor(x/T), ty=Math.floor(y/T);
    return roadsX.includes(tx) || roadsY.includes(ty) || bridgeXs.some(bx=>x>=bx*T @COMMENT_BODY@@COMMENT_BODY@ x<(bx+2)*T @COMMENT_BODY@@COMMENT_BODY@ y>=riverStart-24 @COMMENT_BODY@@COMMENT_BODY@ y<riverEnd+24);
}

function solid(x,y,r=18){
    if(buildings.some(b=>x+r>b.x @COMMENT_BODY@@COMMENT_BODY@ x-r<b.x+b.w @COMMENT_BODY@@COMMENT_BODY@ y+r>b.y @COMMENT_BODY@@COMMENT_BODY@ y-r<b.y+b.h)) return true;
    if(y >= riverStart - 20 @COMMENT_BODY@@COMMENT_BODY@ y < riverEnd + 20){
        for(let bx of bridgeXs){
            let bLeft = bx * T, bRight = (bx + 2) * T;
            if((x - r < bLeft + 12 @COMMENT_BODY@@COMMENT_BODY@ x + r > bLeft) || (x - r < bRight @COMMENT_BODY@@COMMENT_BODY@ x + r > bRight - 12)){
                return true;
            }
        }
    }
    return false;
}

const palette=[
    {wall:'#8c7968', roof:'#57534e', style:'brick'},
    {wall:'#687b80', roof:'#45565a', style:'concrete'},
    {wall:'#98705e', roof:'#654b43', style:'brownstone'},
    {wall:'#8b8a70', roof:'#5d6251', style:'stucco'},
    {wall:'#77727d', roof:'#4e4c58', style:'modern'},
    {wall:'#9c8e78', roof:'#655d50', style:'industrial'}
];

for(let by=0;by<NY;by++) for(let bx=0;bx<NX;bx++){
    if(roadsX.includes(bx)||roadsY.includes(by)) continue;
    let x=bx*T+16, y=by*T+16, w=T-32, h=T-32;
    if(y<riverEnd@COMMENT_BODY@@COMMENT_BODY@y+h>riverStart) continue;
    if(Math.random()<.18){
        parks.push({x,y,w,h,trees:Array.from({length:Math.floor(R(6,12))},()=>({x:R(x+24,x+w-24),y:R(y+24,y+h-24),r:R(20,35)}))});
        continue;
    }
    let arch=P(palette);
    buildings.push({
        x, y, w, h, 
        wall: arch.wall, roof: arch.roof, style: arch.style,
        floors: Math.floor(R(2,6)),
        seed: R(0,100), fade: 0
    });
}

const target={x:3*T+112,y:3*T+112}, warehouse={x:15*T+112,y:10*T+112}, safe={x:2*T+112,y:10*T+112}; let goal=target;

function makeCar(){
    let vertical=Math.random()<.5, road=vertical?P(roadsX):P(roadsY), dir=Math.random()<.5?1:-1;
    let lane=vertical?road*T+(dir>0?76:148):road*T+(dir>0?148:76);
    return {
        x: vertical?lane:R(0,WW), y: vertical?R(0,WH):lane,
        vertical, dir, lane,
        angle: vertical?(dir>0?Math.PI/2:-Math.PI/2):(dir>0?0:Math.PI),
        speed: R(40,75), max: R(70,105),
        color: P(['#a94e3e','#466c84','#c0a66c','#6b865f','#76647c','#c0c0b4','#3c464d','#b85b35','#3e7251']),
        type: P(['SEDAN','COUPE','SUV','TAXI','MUSCLE']),
        ai: true, police: false, damage: 0
    };
}
for(let i=0;i<30;i++) cars.push(makeCar());

function makePed(){
    let x,y; do{x=R(50,WW-50);y=R(50,WH-50);}while(roadAt(x,y)||isWater(x,y)||solid(x,y,16));
    return {
        x, y, angle:R(0,6.28), speed:R(18,32), phase:R(0,6), timer:R(1,5), state:'walk',
        skin:P(['#d9ae8d','#b77d5d','#e2c09e','#9a6b4c']), 
        shirt:P(['#b36b52','#527b80','#a6a06b','#776b91','#c2b39a','#3f5b4e','#c87d55']),
        pants:P(['#303b49','#514b42','#353348','#5a6258']), 
        hair:P(['#292522','#594235','#b29a70','#292d30','#d2b48c']),
        name:P(['Milan','Jelena','Viktor','Nina','Dario','Maja','Luka','Tara','Boris','Iva','Stefan','Ana'])
    };
}
for(let i=0;i<50;i++) peds.push(makePed());

function say(s){ let el=document.querySelector('#toast'); el.textContent=s; el.style.display='block'; toast=3; }
function nearestCar(){ return cars.filter(v=>!v.police@COMMENT_BODY@@COMMENT_BODY@Math.hypot(v.x-player.x,v.y-player.y)<80).sort((a,b)=>Math.hypot(a.x-player.x,a.y-player.y)-Math.hypot(b.x-player.x,b.y-player.y))[0]; }

function interact(){
    if(player.car){
        let v=player.car; player.car=null;
        player.x=v.x+Math.cos(v.angle+1.5)*70; player.y=v.y+Math.sin(v.angle+1.5)*70;
        v.speed=0; say('Izašao si iz vozila.'); return;
    }
    let v=nearestCar();
    if(v){ player.car=v; v.ai=false; say('Ušao si u '+v.type); return; }
    if(Math.hypot(player.x-goal.x,player.y-goal.y)<100){
        if(job===0){job=1; goal=warehouse; say('Zadatak: Preuzmi paket u skladištu pored reke.');}
        else if(job===1){job=2; goal=safe; cash+=650; heat=Math.max(heat,1); say('Paket preuzet! Odnesi ga u skrovište. +$650');}
        else if(job===2){job=3; cash+=1250; heat=0; goal=target; completedJobs++; say('Posao uspešno završen! +$1250. Vrati se na početak za novi posao.');}
        else if(job===3){job=0; goal=target; say('Novi posao je spreman. Priđi markeru i pritisni E.');}
    } else {
        let p=peds.find(q=>Math.hypot(q.x-player.x,q.y-player.y)<60);
        if(p) say(p.name+': „'+P(['Baš je lepo vreme danas.','Pazi se policije u centru.','Sve je duplo veće i prostranije!','Može se lepo zaplivati u reci!'])+'”');
    }
}

addEventListener('keydown',e=>{ let k=e.key.toLowerCase(); keys[k]=true; if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k)) e.preventDefault(); if(k==='e'||k==='enter') interact(); });
addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);

function spawnSparks(x,y,count=6){
    for(let i=0;i<count;i++){
        particles.push({x,y,vx:R(-120,120),vy:R(-120,120),life:R(0.25,0.5),color:P(['#f39c12','#e74c3c','#fff','#bdc3c7'])});
    }
}

function updateCar(v,dt){
    if(!v.ai) return;
    if(v.vertical){
        v.y += Math.sin(v.angle)*v.speed*dt; v.x = v.lane;
        if(Math.abs((v.y/T)%3)<.1 @COMMENT_BODY@@COMMENT_BODY@ Math.random()<dt*.6 @COMMENT_BODY@@COMMENT_BODY@ Math.random()<.35){
            v.vertical=false; v.dir=Math.random()<.5?1:-1;
            v.angle=v.dir>0?0:Math.PI; v.lane=Math.floor(v.y/T)*T+(v.dir>0?148:76);
        }
    } else {
        v.x += Math.cos(v.angle)*v.speed*dt; v.y = v.lane;
        if(Math.abs((v.x/T)%3)<.1 @COMMENT_BODY@@COMMENT_BODY@ Math.random()<dt*.6 @COMMENT_BODY@@COMMENT_BODY@ Math.random()<.35){
            v.vertical=true; v.dir=Math.random()<.5?1:-1;
            v.angle=v.dir>0?Math.PI/2:-Math.PI/2; v.lane=Math.floor(v.x/T)*T+(v.dir>0?76:148);
        }
    }
    if(v.x<0)v.x=WW; if(v.x>WW)v.x=0; if(v.y<0)v.y=WH; if(v.y>WH)v.y=0;
    let front=cars.find(o=>o!==v@COMMENT_BODY@@COMMENT_BODY@o.ai@COMMENT_BODY@@COMMENT_BODY@Math.abs(o.x-v.x)<40@COMMENT_BODY@@COMMENT_BODY@Math.abs(o.y-v.y)<100@COMMENT_BODY@@COMMENT_BODY@Math.cos(v.angle)*(o.x-v.x)+Math.sin(v.angle)*(o.y-v.y)>0);
    v.speed = C(v.speed + (front?-150:60-v.speed)*dt*1.2, 0, v.max);
}

function update(dt){
    if(paused) return;
    minutes = (minutes + dt*3) % 1440;
    weatherTimer -= dt;
    if(weatherTimer <= 0){
        weatherTimer = R(45, 95);
        weatherState = P(['SUNNY', 'RAIN', 'FOG']);
    }

    let obj = player.car || player;
    let up = keys.w||keys.arrowup, down = keys.s||keys.arrowdown, left = keys.a||keys.arrowleft, right = keys.d||keys.arrowright;

    if(player.car){
        let v = player.car;
        let accel = (up?1:0) - (down?1:0);
        v.speed = C(v.speed + accel * 180 * dt, -100, 260);

        if(keys[' ']) {
            v.speed *= Math.pow(0.95, dt*60);
            if(Math.abs(v.speed) > 40 @COMMENT_BODY@@COMMENT_BODY@ Math.random() < 0.6) {
                skidMarks.push({x: v.x - Math.cos(v.angle)*30, y: v.y - Math.sin(v.angle)*30, life: 15});
            }
        } else {
            v.speed *= Math.pow(0.99, dt*60);
        }

        let turnRate = 2.4 * Math.min(1, Math.abs(v.speed)/60) * (v.speed >= 0 ? 1 : -1);
        v.angle += ((right?1:0) - (left?1:0)) * dt * turnRate;

        let nx = v.x + Math.cos(v.angle)*v.speed*dt;
        let ny = v.y + Math.sin(v.angle)*v.speed*dt;

        if(solid(nx, ny, 34) || isWater(nx, ny)){
            v.speed *= -0.4;
            v.damage = C(v.damage + 0.06, 0, 1);
            heat = C(heat + 0.025, 0, 5);
            spawnSparks(v.x, v.y, 12);
            say('Bum! Sudar sa preprekom ili vodom.');
        } else {
            v.x = nx; v.y = ny;
        }

        for(let o of cars){
            if(o !== v @COMMENT_BODY@@COMMENT_BODY@ Math.hypot(o.x - v.x, o.y - v.y) < 52){
                v.speed *= -0.4;
                spawnSparks((v.x+o.x)/2, (v.y+o.y)/2, 8);
                heat = C(heat + 0.03, 0, 5);
            }
        }
    } else {
        let dx = (right?1:0) - (left?1:0), dy = (down?1:0) - (up?1:0);
        let l = Math.hypot(dx,dy) || 1;

        player.isSwimming = isWater(player.x, player.y);
        let speed = player.isSwimming ? 110 : 220;

        let nx = player.x + dx/l * speed * dt, ny = player.y + dy/l * speed * dt;

        if(player.isSwimming){
            if(!solid(nx, player.y, 16)) player.x = nx;
            if(!solid(player.x, ny, 16)) player.y = ny;
            player.swimAnim += dt * 8;
        } else {
            if(!solid(nx, player.y, 18) @COMMENT_BODY@@COMMENT_BODY@ !isWater(nx, player.y)) player.x = nx;
            if(!solid(player.x, ny, 18) @COMMENT_BODY@@COMMENT_BODY@ !isWater(player.x, ny)) player.y = ny;
            player.walk += dt * 10;
        }
    }

    for(let v of cars) updateCar(v, dt);

    for(let p of peds){
        p.phase += dt * 9; p.timer -= dt;
        if(p.timer < 0){ p.state = Math.random() < 0.2 ? 'idle' : 'walk'; p.timer = R(1,4); if(p.state==='walk') p.angle = R(0, 6.28); }
        if(p.state === 'walk'){
            let nx = p.x + Math.cos(p.angle)*p.speed*dt, ny = p.y + Math.sin(p.angle)*p.speed*dt;
            if(solid(nx, ny, 14) || roadAt(nx, ny) || isWater(nx, ny)) p.angle += Math.PI * R(0.7, 1.3);
            else { p.x = nx; p.y = ny; }
        }
    }

    if(heat > 0){
        let cop = cars.find(v=>v.police);
        if(!cop @COMMENT_BODY@@COMMENT_BODY@ Math.random() < dt * 0.15){
            cop = makeCar(); cop.ai = false; cop.police = true;
            cop.x = player.x + R(-400, 400); cop.y = player.y + R(-400, 400);
            cars.push(cop);
        }
        if(cop){
            let targetAngle = Math.atan2(player.y - cop.y, player.x - cop.x);
            cop.angle += (targetAngle - cop.angle) * dt * 3;
            cop.speed = C(cop.speed + 100*dt, 0, 120);
            cop.x += Math.cos(cop.angle) * cop.speed * dt;
            cop.y += Math.sin(cop.angle) * cop.speed * dt;
        }
    }

    for(let i = skidMarks.length - 1; i >= 0; i--){
        skidMarks[i].life -= dt;
        if(skidMarks[i].life <= 0) skidMarks.splice(i, 1);
    }
    for(let i = particles.length - 1; i >= 0; i--){
        let pt = particles[i];
        pt.x += pt.vx * dt; pt.y += pt.vy * dt;
        pt.life -= dt;
        if(pt.life <= 0) particles.splice(i, 1);
    }

    let px = obj.x, py = obj.y;
    cam.x += (C(px - W/2, 0, WW - W) - cam.x) * Math.min(1, dt*6);
    cam.y += (C(py - H/2, 0, WH - H) - cam.y) * Math.min(1, dt*6);

    for(let b of buildings){
        let under = px > b.x @COMMENT_BODY@@COMMENT_BODY@ px < b.x+b.w @COMMENT_BODY@@COMMENT_BODY@ py > b.y @COMMENT_BODY@@COMMENT_BODY@ py < b.y+b.h;
        b.fade += ((under?0.22:0) - b.fade) * Math.min(1, dt*6);
    }

    let h = minutes/60;
    document.querySelector('#cash').textContent = '$ '+cash;
    document.querySelector('#time').textContent = String(Math.floor(h)).padStart(2,'0')+':'+String(Math.floor(h%1*60)).padStart(2,'0');
    document.querySelector('#weather').textContent = weatherState === 'SUNNY' ? '☀️ SUNNY' : (weatherState === 'RAIN' ? '🌧️ RAIN' : '🌫️ FOG');
    document.querySelector('#wanted').textContent = 'POLICE '+'★'.repeat(Math.ceil(heat))+'☆'.repeat(5-Math.ceil(heat));
    document.querySelector('#task').textContent = ['Pronađi govornicu označenu žutim krugom.','Preuzmi paket u skladištu pored reke.','Odnesi paket u skrovište.','Posao završen — pritisni E na početnom markeru za sledeći posao.'][job];
    toast -= dt; if(toast <= 0) document.querySelector('#toast').style.display = 'none';
}

function texturedRect(x,y,w,h,base,n=80,seed=1){
    g.fillStyle=base; g.fillRect(x,y,w,h);
    for(let i=0;i<n;i++){
        let xx=x+((i*73+seed*31)%Math.max(1,w)), yy=y+((i*47+seed*17)%Math.max(1,h));
        g.fillStyle=i%3===0?'rgba(255,255,255,.07)':'rgba(0,0,0,.12)';
        g.fillRect(xx,yy,2+(i%4),2+(i%3));
    }
}

function drawWater(){
    for(let y=riverStart; y<riverEnd; y+=T) for(let x=0; x<WW; x+=T){
        texturedRect(x, y, T, T, '#183a45', 50, x+y);
        g.fillStyle = 'rgba(12, 35, 55, 0.35)'; g.fillRect(x+8, y+8, T-16, T-16);
        g.fillStyle = '#225d5c';
        for(let i=0; i<8; i++) g.fillRect(x + (i*31)%T, y + (i*37)%T, 24, 8);
        g.strokeStyle = 'rgba(85, 130, 140, 0.45)'; g.lineWidth = 2;
        g.beginPath(); g.moveTo(x+20, y+40); g.lineTo(x+80, y+48); g.stroke();
        g.fillStyle = '#2c7280'; g.fillRect(x+40, y+120, 48, 12);
